package school.magiccodex.client;
import java.util.*;import org.junit.jupiter.api.Test;import org.objectweb.asm.ClassReader;import org.objectweb.asm.tree.*;import static org.junit.jupiter.api.Assertions.*;
class SkillKeyDispatchTest {
 private List<String> calls(String n,String m)throws Exception{try(var in=getClass().getResourceAsStream("/school/magiccodex/"+n+".class")){assertNotNull(in);var c=new ClassNode();new ClassReader(in).accept(c,0);var t=c.methods.stream().filter(x->x.name.equals(m)).findFirst().orElseThrow();var r=new ArrayList<String>();for(var i:t.instructions)if(i instanceof MethodInsnNode x)r.add(x.owner+"."+x.name);return r;}}
 @Test void skillsPrecedeAllUiShortcutsAndKeepMatchReservation()throws Exception{var c=calls("mixin/CodexKeyboardMixin","magiccodex$openShortcut");int k=c.indexOf("school/magiccodex/client/CastingClient.handleKey");assertTrue(k>=0);for(String n:List.of("PlayerHudClient.handleCursorKey","UiKeys.handleKey","EquipmentClient.handleKey","StatsClient.handleKey","MagicCodexClient.handleOpenShortcut"))assertTrue(k<c.indexOf("school/magiccodex/client/"+n),n);assertTrue(c.indexOf("school/magiccodex/client/KyudichiClient.reservesKey")<k);assertTrue(calls("client/CastingClient","handleKey").contains("school/magiccodex/client/CastingState$Result.consumed"));}
 @Test void heldQueuedReboundAttackAndModKeysUseGuardedSuppression()throws Exception{for(String m:List.of("magiccodex$blockHeldVanillaKey","magiccodex$blockQueuedVanillaKey"))assertTrue(calls("mixin/CastingKeyBindingMixin",m).contains("school/magiccodex/client/CastingClient.suppressed"));var c=calls("client/CastingClient","suppressed");assertTrue(c.contains("net/minecraft/client/option/KeyBinding.matchesKey"));assertTrue(c.contains("net/minecraft/client/option/KeyBinding.matchesMouse"));assertFalse(c.contains("net/minecraft/client/option/KeyBinding.getTranslationKey"));assertTrue(c.contains("school/magiccodex/client/CastingClient.gameplay"));}
}
